func TestCategorizeTool(t *testing.T) {
	t.Parallel()
	cases := []struct {
		toolName, bashCommand, want string
	}{
		{"Bash", "ls -la", "shell"},
		{"Bash", "git commit -m 'foo'", "commit"},
