func TestLoadActivity_SingleLocalSession(t *testing.T) {
	repo := newIsolatedRepo(t)
	started := time.Now().Add(-2 * time.Hour)
	writeSessionState(t, repo, &session.State{
		SessionID:    "sess-1",
		BaseCommit:   "abc1234",
		StartedAt:    started,
		StepCount:    3,
		FilesTouched: []string{"cmd/entire/cli/checkpoint/store.go"},
		WorktreePath: repo,
	})
	out, err := LoadActivity(ctx(), LoadOpts{Scope: ScopeLocal})
	if err != nil {
		t.Fatal(err)
	}
	if len(out.Sessions) != 1 {
		t.Fatalf("expected 1 session, got %d", len(out.Sessions))
	}
	s := out.Sessions[0]
	if s.SessionID != "sess-1" {
		t.Errorf("wrong session id: %s", s.SessionID)
	}
	if got := s.FocusAreas; len(got) != 1 || got[0] != "checkpoint storage" {
		t.Errorf("expected focus area 'checkpoint storage', got %v", got)
	}
	if s.Source != SourceLocal {
		t.Errorf("expected SourceLocal, got %v", s.Source)
	}
}

func TestLoadOpts_Defaults(t *testing.T) {
	t.Parallel()
	opts := LoadOpts{}
