package activity

import (
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	_ "github.com/entireio/cli/cmd/entire/cli/agent/claudecode" // register claude-code in the agent registry
	_ "github.com/entireio/cli/cmd/entire/cli/agent/codex"      // register codex in the agent registry
)

// fixtureTranscript is a 5-line Claude-Code-shaped JSONL used by load_test.go too.
const fixtureTranscript = `{"type":"assistant","timestamp":"2026-04-15T10:00:00Z","message":{"content":[{"type":"tool_use","name":"Bash","input":{"command":"ls -la"}}]}}
{"type":"user","timestamp":"2026-04-15T10:01:00Z","message":{"content":[{"type":"tool_result","tool_use_id":"x"}]}}
{"type":"assistant","timestamp":"2026-04-15T10:02:00Z","message":{"content":[{"type":"text","text":"let me think"},{"type":"tool_use","name":"Edit","input":{"file_path":"foo.go"}}]}}
{"type":"user","timestamp":"2026-04-15T10:03:00Z","message":{"content":[{"type":"tool_result","tool_use_id":"y"}]}}
{"type":"assistant","timestamp":"2026-04-15T10:04:00Z","message":{"content":[{"type":"tool_use","name":"Bash","input":{"command":"git commit -m foo"}}]}}
`

func TestComputeToolProfile_Counts(t *testing.T) {
	t.Parallel()
	t0, _ := time.Parse(time.RFC3339, "2026-04-15T10:00:00Z")
	calls := []agent.ToolCall{
		{Name: "Bash", BashCommand: "ls -la", Timestamp: t0},
		{Name: "Edit", Timestamp: t0.Add(2 * time.Minute)},
		{Name: "Bash", BashCommand: "git commit -m foo", Timestamp: t0.Add(4 * time.Minute)},
	}
	p := ComputeToolProfile(calls)
	if p.Total != 3 {
		t.Errorf("total = %d, want 3", p.Total)
	}
	if got := p.Categories[CategoryShell].Count; got != 1 {
		t.Errorf("shell count = %d, want 1", got)
	}
	if got := p.Categories[CategoryFileOps].Count; got != 1 {
		t.Errorf("fileOps count = %d, want 1", got)
	}
	if got := p.Categories[CategoryCommit].Count; got != 1 {
		t.Errorf("commit count = %d, want 1", got)
	}
}

func TestComputeToolProfile_Durations(t *testing.T) {
	t.Parallel()
	t0, _ := time.Parse(time.RFC3339, "2026-04-15T10:00:00Z")
	calls := []agent.ToolCall{
		{Name: "Bash", BashCommand: "ls -la", Timestamp: t0},
		{Name: "Edit", Timestamp: t0.Add(2 * time.Minute)},
		{Name: "Bash", BashCommand: "git commit -m foo", Timestamp: t0.Add(4 * time.Minute)},
	}
	p := ComputeToolProfile(calls)
	if got := p.Categories[CategoryShell].DurationMs; got != 120_000 {
		t.Errorf("shell duration = %d ms, want 120000", got)
	}
	if got := p.Categories[CategoryFileOps].DurationMs; got != 120_000 {
		t.Errorf("fileOps duration = %d ms, want 120000", got)
	}
	if got := p.Categories[CategoryCommit].DurationMs; got != 0 {
		t.Errorf("commit duration = %d, want 0 (last call has no successor)", got)
	}
}

func TestComputeToolProfile_EmptyInput(t *testing.T) {
	t.Parallel()
	p := ComputeToolProfile(nil)
	if p.Total != 0 {
		t.Errorf("expected zero total, got %d", p.Total)
	}
}

func TestDeriveToolTime_ClaudeCodeDispatch(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	path := filepath.Join(dir, "t.jsonl")
	if err := os.WriteFile(path, []byte(fixtureTranscript), 0o644); err != nil {
		t.Fatal(err)
	}
	p, err := DeriveToolTime("Claude Code", path)
	if err != nil {
		t.Fatal(err)
	}
	if p == nil {
		t.Fatal("expected non-nil profile")
	}
	if p.Total != 3 {
		t.Errorf("total = %d, want 3", p.Total)
	}
}

func TestDeriveToolTime_UnknownAgent(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	path := filepath.Join(dir, "t.jsonl")
	if err := os.WriteFile(path, []byte(fixtureTranscript), 0o644); err != nil {
		t.Fatal(err)
	}
	p, err := DeriveToolTime("NotARealAgent", path)
	if err != nil {
		t.Errorf("unknown agent should be silent; got err: %v", err)
	}
	if p != nil {
		t.Errorf("expected nil profile, got %+v", p)
	}
}

func TestDeriveToolTime_EmptyPath(t *testing.T) {
	t.Parallel()
	p, err := DeriveToolTime("Claude Code", "")
	if err != nil {
		t.Fatal(err)
	}
	if p != nil {
		t.Errorf("expected nil profile, got %+v", p)
	}
}

