	if name != "exec_command" && name != "shell" && name != "local_shell" {
		return ""
	}
	if args == "" {
		return ""
	}
	var v struct {
		Cmd     string   `json:"cmd,omitempty"`
		Command []string `json:"command,omitempty"` // some local_shell shapes use []string
	}
	if err := json.Unmarshal([]byte(args), &v); err != nil {
		return ""
	}
	if v.Cmd != "" {
		return v.Cmd
	}
	if len(v.Command) > 0 {
		// Join as a best-effort single string for downstream regex matching.
		return strings.Join(v.Command, " ")
	}
	return ""
}

