`
	dir, err := os.MkdirTemp("", "activity-demo-*")
	if err != nil {
		fmt.Fprintln(os.Stderr, "mkdir temp:", err)
		return
	}
	defer os.RemoveAll(dir)
	path := filepath.Join(dir, "transcript.jsonl")
	if err := os.WriteFile(path, []byte(transcript), 0o644); err != nil {
		fmt.Fprintln(os.Stderr, "write fixture:", err)
		return
	}
	profile, err := activity.DeriveToolTime("Claude Code", path)
	if err != nil {
		fmt.Fprintln(os.Stderr, "DeriveToolTime error:", err)
		return
	}
